spec.query:
from(bucket: "smarthomederived")
  |> range(start: today())
  |> filter(fn: (r) =>
    r._measurement == "daily_energy" and
    (
      r._field == "green_upstream" or
      r._field == "green_injected"
    )
  )
  |> pivot(
      rowKey: ["_time"],
      columnKey: ["_field"],
      valueColumn: "_value"
  )
  |> map(fn: (r) => ({
      _time: r._time,
      _measurement: "upstream ratio",
      _field: "eta",
      _value: -1.0 * r.green_upstream / r.green_injected
  }))

from(bucket: "smarthomederived")
|> range(start: today())
|> filter(fn: (r) => r._measurement == "daily_energy" and r._field == "green_upstream" )
|> map(fn: (r) => ({
    r with
    _value: r._value * -1.0
}))
|> last()

from(bucket: "smarthomederived")
  |> range(start: today())
  |> filter(fn: (r) => r._measurement == "daily_energy")
  |> filter(fn: (r) =>
      r._field == "green_used" or
      r._field == "green_upstream" or
      r._field == "swm_used"
  )
  |> last()
  |> map(fn: (r) => ({
      r with
      _value: if r._field == "green_upstream" then r._value * -1.0 else r._value
  }))

import "math"
from(bucket: "smarthome")
  |> range(start: -3h)
  |> filter(fn: (r) => 
    (r._measurement == "tasmota" and (r._field == "downstream" or r._field == "upstream")) or
    (r._measurement == "zendure" and r._field == "outputHomePower")
  )
  |> drop(columns: ["domain","electric","room"])
  |> last()
  |> map(fn: (r) => ({
      r with
      _value: math.abs(x: float(v: r._value))
  }))
